import json
with open('/tmp/woo_searchproducts_def.json') as f:
    d = json.load(f)
node = d.get('Data', {}).get('Node', {})
form = node.get('form', {})
sections = form.get('sections', [])
# Print all fields
for sec in sections:
    for fld in sec.get('fields', []):
        name = fld.get('name','')
        cp = fld.get('componentProps', {})
        cd = cp.get('connectorDetail', {})
        config_raw = cd.get('configuration', '')
        try:
            config = json.loads(config_raw) if config_raw else {}
        except:
            config = {'raw': config_raw}
        if 'attribute_term' in name or 'attribute' in name:
            print(f'FIELD: {name}')
            print(json.dumps(fld, indent=2))
" 2>/dev/null | head -200

